templates.template:
/* =============================================================================
   MKOW — a XenForo 2.3 port of the ProBoards "MKOW VIP" skin by Silent of IncrediBAD.
   Charcoal page, a dark rounded frame with the teal hex menu bar, the Modern Knights of
   Warfare emblem panels, dark title bars and near-black rows with teal links.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */

@mk-teal: #1c86a8;
@mk-teal-hover: #4cb6d8;
@mk-text: #8d8d8d;
@mk-titlebg: linear-gradient(180deg, #2e2d2e 0%, #242324 50%, #111 100%);

:root
{
	color-scheme: dark;
}

html
{
	background: #1a1a1a;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The framed 896px column ------------------------------------------------------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 896px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header
{
	padding-top: 12px;
}

.p-header-content
{
	height: 28px;
	padding: 0;
	background: url("data:image/png;base64,") center bottom / 896px 28px no-repeat;
}

// The emblem panels replace the logo. Delete this rule to show the logo from Style properties.
.p-header-logo
{
	display: none;
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

// Teal hex menu bar, then the emblem panels underneath it
.p-nav
{
	color: #e6f4f8;
}

.p-nav-inner
{
	padding: 0 20px 302px;
	background:
		url("data:image/jpeg;base64,") center top / 896px 32px no-repeat,
		url("data:image/jpeg;base64,") center 32px / 896px 302px no-repeat;
}

.p-nav-scroller,
.p-nav-opposite
{
	height: 32px;
	align-items: center;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #e6f4f8;
		font-family: 'Eurostile', 'Bank Gothic', 'Michroma', 'Trebuchet MS', sans-serif;
		font-size: 15px;
		font-variant: small-caps;
		letter-spacing: 2px;
		line-height: 18px;
		padding: 7px 12px;
		text-shadow: 0 0 6px rgba(76, 182, 216, .8), 0 1px 1px #000;

		&:hover
		{
			color: #fff;
			text-decoration: none;
			text-shadow: 0 0 8px #4cb6d8, 0 1px 1px #000;
		}
	}

	.p-navEl.is-selected
	{
		background: transparent;

		.p-navEl-link
		{
			color: #fff;
			text-shadow: 0 0 10px #4cb6d8, 0 1px 1px #000;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #e6f4f8;

	&:hover
	{
		background: rgba(76, 182, 216, .15);
		color: #fff;
		text-decoration: none;
	}
}

.p-sectionLinks-inner,
.p-body-inner
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA4AAAAAECAIAAABQn8ZTAAAATklEQVR42u3WsQnAIBRFURMENxAb9x/M5v8hhFTJAoEU4Zzyla+6R2ut3PbeY4w5Z2YWAAB4p/ceEWutWusznn4BAOBLAhQAAAEKAMB/XcCODB2zE/DJAAAAAElFTkSuQmCC") center top / 896px 4px repeat-y;
	padding-left: 34px;
	padding-right: 34px;
}

.p-sectionLinks-inner a
{
	color: @mk-teal;
}

.p-body-inner
{
	color: @mk-text;
	padding-bottom: 20px;
}

.p-title-value
{
	color: #f1f1f1;
}

// ---- Blocks: dark title bars, near-black rows, black borders ----------------------------

.block-container
{
	background: #111;
	border: 1px solid #000;
	border-radius: 0;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: @mk-titlebg;
	border-bottom: 1px solid #000;
	color: #f1f1f1;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #f1f1f1;
	}

	.block-desc
	{
		color: @mk-text;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: @mk-text;

	&:hover
	{
		color: #f1f1f1;
	}

	&.is-active
	{
		color: #f1f1f1;
		border-color: @mk-teal;
	}
}

.block-footer
{
	background: linear-gradient(180deg, #2d2d2d 0%, #1f1f1f 100%);
	border-top-color: #000;
	color: @mk-text;
}

.node + .node
{
	border-top: 1px solid #2e2e2e;
}

.node-body,
.structItem
{
	background: #111;
}

.structItem
{
	border-top-color: #2e2e2e;
}

.node-title a,
.structItem-title a
{
	color: @mk-teal;
	font-weight: 700;

	&:hover
	{
		color: @mk-teal-hover;
	}
}

.node-description,
.node-meta,
.node-stats,
.structItem-minor
{
	color: @mk-text;
}

// The skin's dark forum icon: lit with a teal glow when there are new posts.
.node--forum .node-icon i
{
	display: block;
	width: 36px;
	height: 32px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / 36px 32px no-repeat;
	border-radius: 50%;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	box-shadow: 0 0 8px 2px rgba(76, 182, 216, .65);
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: @mk-teal;
	}
}

.message,
.message-inner
{
	background: #111;
	border-color: #000;
}

.message-cell--user
{
	background: #181818;
	border-right-color: #000;
}

.message-body
{
	color: #b4b4b4;
}

.message-userArrow::after
{
	border-right-color: #111;
}

.bbCodeBlock
{
	background: #1a1a1a;
	border-color: #2e2e2e;
}

.input
{
	background: #0d0d0d;
	border-color: #2e2e2e;
	color: #c8c8c8;

	&:focus
	{
		border-color: @mk-teal;
	}
}

.menu-content,
.overlay
{
	background: #181818;
	border: 1px solid #000;
	color: @mk-text;
}

.overlay-title
{
	background: @mk-titlebg;
	color: #f1f1f1;
}

.button,
a.button
{
	background: @mk-titlebg;
	border: 1px solid #000;
	color: #e6f4f8;

	&:hover
	{
		background: linear-gradient(180deg, #3a393a 0%, #2c2b2c 50%, #1a1a1a 100%);
		color: #fff;
	}
}

.button.button--primary,
a.button.button--primary
{
	background: linear-gradient(180deg, #1c86a8 0%, #0d6279 100%);
	border-color: #08414f;
	color: #fff;
}

// ---- Footer: the frame's rounded base, then the skin credit --------------------------------

.p-footer
{
	background: transparent;
	color: @mk-text;

	&::before
	{
		content: '';
		display: block;
		max-width: 896px;
		height: 16px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 896px 16px no-repeat;
	}

	a
	{
		color: @mk-teal;

		&:hover
		{
			color: @mk-teal-hover;
		}
	}
}

.p-footer-copyright::after
{
	content: "MKOW skin created by Silent of IncrediBAD";
	display: block;
	margin-top: 4px;
}

// ---- Narrower than the 896px frame: scale the artwork, plain dark column ----------------

@media (max-width: 915px)
{
	.p-header
	{
		padding-top: 0;
	}

	.p-header-content
	{
		display: none;
	}

	.p-nav-inner
	{
		padding: 0 10px calc(~'100vw * 302 / 896');
		background-size: 100% 32px, 100% auto;
		background-color: #222;
	}

	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: #222;
		padding-left: 10px;
		padding-right: 10px;
	}

	.p-footer::before
	{
		background-size: 100% 16px;
	}
}
